mapper.select:
SELECT DISTINCT a.AREA_DSCR as name,  as value
FROM visual_screen.vs_budget_revenue a
WHERE 1 = 1
and INDEX_NAME = #{params.INDEX_NAME}
and a.AREA_CODE not in ('500000','500999','500996')

    ${params.whereInfo}


    and PERIOD_FLAG = #{params.PERIOD_FLAG}

group by a.AREA_DSCR
order by  desc

SELECT DISTINCT a.AREA_DSCR as name, as value FROM visual_screen.vs_budget_revenue a left join visual_screen.vs_budget_revenue a1 ON a1.DACCT = AND a.AREA_CODE = a1.AREA_CODE and a1.INDEX_NAME = #{params.INDEX_NAME} and a1.AREA_CODE not in ('500000','500999','500996') WHERE 1 = 1 and a.INDEX_NAME = #{params.INDEX_NAME} and a.AREA_CODE not in ('500000','500999','500996')
${params.whereInfo}
and a.PERIOD_FLAG = #{params.PERIOD_FLAG}
group by a.AREA_DSCR order by desc

SELECT COALESCE(ROUND(MAX(a.INDEX_VALUE), 2), 0) as max_value,
       COALESCE(ROUND(MIN(a.INDEX_VALUE), 2), 0) as min_value
FROM (
    SELECT DISTINCT  as INDEX_VALUE
    FROM visual_screen.vs_budget_revenue a
    WHERE 1 = 1
    and INDEX_NAME = #{params.INDEX_NAME}
    and a.AREA_CODE not in ('500000','500999','500996')

        ${params.whereInfo}


        and PERIOD_FLAG = #{params.PERIOD_FLAG}

    group by a.AREA_DSCR
) a

SELECT DISTINCT a.AREA_DSCR as AREA_DSCR,  as INDEX_VALUE
FROM visual_screen.vs_budget_revenue a
WHERE 1 = 1
and INDEX_NAME = #{params.INDEX_NAME}
and a.AREA_CODE in ('500000','500999','500996')

    ${params.whereInfo}


    and PERIOD_FLAG = #{params.PERIOD_FLAG}

group by a.AREA_DSCR, a.AREA_CODE
order by a.AREA_CODE

SELECT DISTINCT a.AREA_DSCR as AREA_DSCR, as INDEX_VALUE FROM visual_screen.vs_budget_revenue a left join visual_screen.vs_budget_revenue a1 ON a1.DACCT = AND a.AREA_CODE = a1.AREA_CODE and a1.AREA_CODE in ('500000','500999','500996') and a1.INDEX_NAME = #{params.INDEX_NAME} WHERE 1 = 1 and a.INDEX_NAME = #{params.INDEX_NAME} and a.AREA_CODE in ('500000','500999','500996')
${params.whereInfo}
and a.PERIOD_FLAG = #{params.PERIOD_FLAG}
group by a.AREA_DSCR, a.AREA_CODE order by a.AREA_CODE

